// Fetches Gen-1 Pokémon data + FireRed/LeafGreen sprites from PokeAPI.
// Outputs: assets/data/pokedex.js, assets/data/moves.js, assets/sprites/{front,back}/{id}.png
import { mkdir, writeFile } from 'node:fs/promises';
import path from 'node:path';

const ROOT = path.resolve(import.meta.dirname, '..');
const API = 'https://pokeapi.co/api/v2';
const SPRITES = 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/versions/generation-iii/firered-leafgreen';

async function getJSON(url, tries = 3) {
  for (let i = 0; i < tries; i++) {
    try {
      const r = await fetch(url);
      if (r.ok) return r.json();
      if (r.status === 404) return null;
    } catch (e) { /* retry */ }
    await new Promise(res => setTimeout(res, 800 * (i + 1)));
  }
  throw new Error('failed: ' + url);
}

async function getBin(url, tries = 3) {
  for (let i = 0; i < tries; i++) {
    try {
      const r = await fetch(url);
      if (r.ok) return Buffer.from(await r.arrayBuffer());
      if (r.status === 404) return null;
    } catch (e) { /* retry */ }
    await new Promise(res => setTimeout(res, 800 * (i + 1)));
  }
  throw new Error('failed: ' + url);
}

// Limit concurrency to be polite to the API.
async function pool(items, n, fn) {
  const out = new Array(items.length);
  let i = 0;
  await Promise.all(Array.from({ length: n }, async () => {
    while (i < items.length) {
      const idx = i++;
      out[idx] = await fn(items[idx], idx);
    }
  }));
  return out;
}

console.log('Fetching 151 Pokémon...');
const ids = Array.from({ length: 151 }, (_, i) => i + 1);

const mons = await pool(ids, 8, async (id) => {
  const [p, s] = await Promise.all([
    getJSON(`${API}/pokemon/${id}`),
    getJSON(`${API}/pokemon-species/${id}`),
  ]);
  const stats = {};
  for (const st of p.stats) stats[st.stat.name] = st.base_stat;
  // FRLG level-up learnset
  const learnset = [];
  for (const m of p.moves) {
    for (const d of m.version_group_details) {
      if (d.version_group.name === 'firered-leafgreen' && d.move_learn_method.name === 'level-up') {
        learnset.push({ level: d.level_learned_at, move: m.move.name });
      }
    }
  }
  learnset.sort((a, b) => a.level - b.level);
  process.stdout.write(`\r  pokemon ${id}/151   `);
  return {
    id,
    name: p.name,
    displayName: s.names.find(n => n.language.name === 'en')?.name ?? p.name,
    types: p.types.sort((a, b) => a.slot - b.slot).map(t => t.type.name),
    stats: {
      hp: stats.hp, atk: stats.attack, def: stats.defense,
      spa: stats['special-attack'], spd: stats['special-defense'], spe: stats.speed,
    },
    baseExp: p.base_experience,
    catchRate: s.capture_rate,
    growth: s.growth_rate.name,
    evoChainId: Number(s.evolution_chain.url.match(/\/(\d+)\/?$/)[1]),
    learnset,
    evolvesTo: [], // filled from chains below
  };
});
console.log('\nFetching evolution chains...');

const byName = new Map(mons.map(m => [m.name, m]));
const chainIds = [...new Set(mons.map(m => m.evoChainId))];
await pool(chainIds, 8, async (cid) => {
  const chain = await getJSON(`${API}/evolution-chain/${cid}`);
  const walk = (node) => {
    const from = byName.get(node.species.name);
    for (const next of node.evolves_to) {
      const to = byName.get(next.species.name);
      if (from && to) {
        const d = next.evolution_details[0] ?? {};
        let evo = null;
        if (d.trigger?.name === 'level-up' && d.min_level) {
          evo = { to: to.id, method: 'level', level: d.min_level };
        } else if (d.trigger?.name === 'use-item') {
          evo = { to: to.id, method: 'stone', item: d.item.name };
        } else if (d.trigger?.name === 'trade') {
          // Trade evolutions become level-up so everything is obtainable single-player.
          evo = { to: to.id, method: 'level', level: 37 };
        }
        if (evo) from.evolvesTo.push(evo);
      }
      walk(next);
    }
  };
  walk(chain.chain);
});

// Collect every move referenced by any learnset, fetch details.
const moveNames = [...new Set(mons.flatMap(m => m.learnset.map(l => l.move)))];
console.log(`Fetching ${moveNames.length} moves...`);
const moves = {};
await pool(moveNames, 8, async (name, idx) => {
  const mv = await getJSON(`${API}/move/${name}`);
  process.stdout.write(`\r  move ${idx + 1}/${moveNames.length}   `);
  moves[name] = {
    name,
    displayName: mv.names.find(n => n.language.name === 'en')?.name ?? name,
    type: mv.type.name,
    power: mv.power,
    accuracy: mv.accuracy,
    pp: mv.pp,
    priority: mv.priority,
    damageClass: mv.damage_class.name, // physical/special/status (we re-derive phys/spec by type for Gen 3)
    ailment: mv.meta?.ailment?.name !== 'none' ? mv.meta?.ailment?.name : null,
    ailmentChance: mv.meta?.ailment_chance ?? 0,
    statChanges: mv.stat_changes.map(sc => ({ stat: sc.stat.name, change: sc.change })),
    statChance: mv.meta?.stat_chance ?? 0,
    drain: mv.meta?.drain ?? 0,
    healing: mv.meta?.healing ?? 0,
    flinch: mv.meta?.flinch_chance ?? 0,
    critRate: mv.meta?.crit_rate ?? 0,
    minHits: mv.meta?.min_hits,
    maxHits: mv.meta?.max_hits,
    target: mv.target.name,
  };
});

console.log('\nDownloading sprites...');
await mkdir(path.join(ROOT, 'assets/sprites/front'), { recursive: true });
await mkdir(path.join(ROOT, 'assets/sprites/back'), { recursive: true });
let missing = [];
await pool(ids, 8, async (id) => {
  let front = await getBin(`${SPRITES}/${id}.png`);
  let back = await getBin(`${SPRITES}/back/${id}.png`);
  // Fallback to default modern sprites if FRLG art is missing.
  if (!front) front = await getBin(`https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/${id}.png`);
  if (!back) back = await getBin(`https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/back/${id}.png`);
  if (!front || !back) { missing.push(id); return; }
  await writeFile(path.join(ROOT, `assets/sprites/front/${id}.png`), front);
  await writeFile(path.join(ROOT, `assets/sprites/back/${id}.png`), back);
  process.stdout.write(`\r  sprite ${id}/151   `);
});
if (missing.length) console.log('\nMISSING SPRITES:', missing);

await mkdir(path.join(ROOT, 'assets/data'), { recursive: true });
const dex = {};
for (const m of mons) { delete m.evoChainId; dex[m.id] = m; }
await writeFile(path.join(ROOT, 'assets/data/pokedex.js'),
  'window.POKEDEX = ' + JSON.stringify(dex) + ';\n');
await writeFile(path.join(ROOT, 'assets/data/moves.js'),
  'window.MOVES = ' + JSON.stringify(moves) + ';\n');
console.log('\nDone. Wrote pokedex.js (' + mons.length + ' mons), moves.js (' + moveNames.length + ' moves).');
